set -euo pipefail
export DEBIAN_FRONTEND=noninteractive
apt-get update
apt-get install -y nginx
python3 - <<'PY'
from pathlib import Path
import re
p = Path('/etc/nginx/nginx.conf')
text = p.read_text()
if 'log_format benchmark_fmt' not in text or 'limit_req_zone $binary_remote_addr zone=bench_zone:10m rate=10r/s;' not in text:
    lines = text.splitlines()
    out = []
    inserted = False
    for line in lines:
        out.append(line)
        if (not inserted) and re.match(r'^\s*http\s*\{\s*$', line):
            out.append('    log_format benchmark_fmt \'' + '$time_local $request_method $status "$http_user_agent"' + '\';')
            out.append('    limit_req_zone $binary_remote_addr zone=bench_zone:10m rate=10r/s;')
            inserted = True
    if not inserted:
        raise SystemExit('http block not found in nginx.conf')
    p.write_text('\n'.join(out) + '\n')
site = Path('/etc/nginx/conf.d/benchmark-site.conf')
site.parent.mkdir(parents=True, exist_ok=True)
site.write_text('''server {
    listen 8080;
    server_name localhost;
    root /var/www/html;
    index index.html;
    access_log /var/log/nginx/benchmark-access.log benchmark_fmt;
    error_log /var/log/nginx/benchmark-error.log;
    limit_req zone=bench_zone burst=10;
    error_page 404 /404.html;
    location / {
        try_files $uri $uri/ =404;
    }
    location = /404.html {
        internal;
    }
}
''')
Path('/var/www/html').mkdir(parents=True, exist_ok=True)
Path('/var/log/nginx').mkdir(parents=True, exist_ok=True)
Path('/var/www/html/index.html').write_text('Welcome to the benchmark webserver')
Path('/var/www/html/404.html').write_text('Page not found - Please check your URL')
Path('/var/log/nginx/benchmark-access.log').touch(exist_ok=True)
Path('/var/log/nginx/benchmark-error.log').touch(exist_ok=True)
PY
